import { useEffect, useState } from 'react';
import { SafeAreaView, Text } from 'react-native';
import { createChannel, createBytesChannel } from '@rustra/react-native';
import { rustra, emitDemo, subscribeEvent, add, channelDemo, channelDemoBytes } from './generated/react-native';

const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));
const marker = 'RUSTRA_IOS_EVENT_AUDIT=';
const check = (condition: boolean, message: string) => { if (!condition) throw new Error(message); };

async function audit() {
  console.log(marker + JSON.stringify({ phase: 'start' }));
  const coldStart = performance.now();
  await rustra.ready();
  check(await add(42, 58) === 100, 'initial Rust call');
  const readyAndFirstCallMs = performance.now() - coldStart;
  console.log(marker + JSON.stringify({ phase: 'ready' }));
  const seen: number[] = [];
  let done = 0;
  const off = subscribeEvent('progress.tick', (value: any) => seen.push(value.step));
  const offDone = subscribeEvent('demo.done', () => { done++; });
  const emitted = await emitDemo({ ticks: 3, stepDelayMs: 0 });
  check(Number(emitted.emitted) === 4, 'Rust emitted count');
  console.log(marker + JSON.stringify({ phase: 'invoke-returned', emitted: Number(emitted.emitted) }));
  await wait(100);
  check(JSON.stringify(seen) === '[1,2,3]' && done === 1, `push delivery ${JSON.stringify({seen,done})}`);
  off(); offDone();
  await emitDemo({ ticks: 2, stepDelayMs: 0 });
  await wait(100);
  check(seen.length === 3 && done === 1, 'delivery after unsubscribe');
  console.log(marker + JSON.stringify({ phase: 'push-and-unsubscribe-ok' }));

  let reentrant = 0;
  let offReentrant = () => {};
  // Keep one listener registered so resubscription mutates the same live Set.
  const anchor = subscribeEvent('progress.tick', () => {});
  const listener = () => { reentrant++; offReentrant(); offReentrant = subscribeEvent('progress.tick', listener); };
  offReentrant = subscribeEvent('progress.tick', listener);
  await emitDemo({ ticks: 1, stepDelayMs: 0 });
  await wait(100);
  check(reentrant === 1, `resubscription repeated ${reentrant} times`);
  offReentrant(); anchor();

  let cycleEvents = 0;
  for (let cycle = 0; cycle < 100; cycle++) {
    const unsubscribe = subscribeEvent('progress.tick', () => { cycleEvents++; });
    await emitDemo({ ticks: 1, stepDelayMs: 0 });
    await wait(5);
    check(cycleEvents === cycle + 1, `cycle ${cycle}: ${cycleEvents} deliveries`);
    unsubscribe();
  }
  await emitDemo({ ticks: 1, stepDelayMs: 0 }); await wait(100);
  check(cycleEvents === 100, 'cycle listener leaked');

  const messages: unknown[] = [];
  const channel = createChannel(value => messages.push(value));
  await channelDemo({ channel: channel.handle, ticks: 3 }); await wait(100);
  check(messages.length === 3, `channel delivery ${messages.length}`);
  check(channel.close() && !channel.close(), 'channel close must be idempotent');
  const bytes: Uint8Array[] = [];
  const binary = createBytesChannel(value => bytes.push(value));
  await channelDemoBytes({ channel: binary.handle, ticks: 3 }); await wait(100);
  check(bytes.length === 3 && bytes.every(value => value.length === 8), 'binary channel delivery');
  check(binary.close() && !binary.close(), 'binary channel close must be idempotent');
  check(await add(1, 2) === 3, 'Rust call after teardown');
  for (let i = 0; i < 100; i++) check(await add(1, 2) === 3, 'warmup call');
  const samples: number[] = [];
  for (let i = 0; i < 1000; i++) {
    const started = performance.now();
    const result = await add(1, 2);
    samples.push((performance.now() - started) * 1000);
    check(result === 3, 'measured call');
  }
  const sorted = [...samples].sort((a,b) => a-b);
  const benchmark = { unit: 'microseconds', route: 'generated add(1,2), awaited',
    warmup: 100, observations: samples.length, p50: sorted[499], p95: sorted[949],
    mean: samples.reduce((a,b)=>a+b,0)/samples.length, readyAndFirstCallMs };
  for (let index = 0; index < 50; index++) {
    console.log('RUSTRA_IOS_EVENT_SAMPLES=' + JSON.stringify({ index, samples: samples.slice(index * 20, (index + 1) * 20) }));
  }
  const result = { phase: 'complete', ok: true, pushEvents: seen, unsubscribeAdditional: 0,
    resubscribeEvents: reentrant, subscriptionCycles: 100, channelMessages: messages.length,
    binaryChannelMessages: bytes.length, finalRustCall: 3, benchmark };
  console.log(marker + JSON.stringify(result));
  return result;
}

export default function AuditEventsApp() {
  const [status, setStatus] = useState('검증 중');
  useEffect(() => {
    audit().then(() => setStatus('검증 통과')).catch(error => {
      console.log(marker + JSON.stringify({ phase: 'failure', error: String(error) }));
      setStatus(String(error));
    });
  }, []);
  return <SafeAreaView><Text>Rustra Simulator Audit</Text><Text>{status}</Text></SafeAreaView>;
}

